import{K as n,a as r,c as i,b as t,k as l,q as s,ac as h}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"OneNote 笔记本、分区与会议记录","description":"从笔记本到分区页面建立 OneNote 组织结构，记录会议决策、行动项、附件和来源，检查同步并区分链接与文件副本。","frontmatter":{"title":"OneNote 笔记本、分区与会议记录","description":"从笔记本到分区页面建立 OneNote 组织结构，记录会议决策、行动项、附件和来源，检查同步并区分链接与文件副本。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · OneNote 笔记管理","summary":"从笔记本到分区页面建立 OneNote 组织结构，记录会议决策、行动项、附件和来源，检查同步并区分链接与文件副本。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":false,"next":{"text":"OneNote 搜索、标签、模板与知识整理","link":"/tools/office/onenote/knowledge"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"OneNote 搜索、标签、模板与知识整理","link":"/tools/office/onenote/knowledge"}},"headers":[],"relativePath":"tools/office/onenote/notes.md","filePath":"tools/office/onenote/notes.md"}'),c={name:"tools/office/onenote/notes.md"},g=Object.assign(c,{setup(d){const o={path:"/tools/office/onenote/notes",app:"OneNote",title:"把一次会议整理成可追踪的笔记",steps:[{tab:"文件",command:"新建",setting:"笔记本：月报项目；保存位置：可同步的位置",anchor:"walkthrough-1"},{tab:"开始",command:"待办事项标记",setting:"行动项：负责人 + 截止时间 + 结果",anchor:"walkthrough-2"},{tab:"文件",command:"查看同步状态",setting:"确认同步完成；重新打开页面检查",anchor:"walkthrough-3"}]};return(p,e)=>{const a=n("OfficeGuide");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"onenote-笔记本、分区与会议记录",tabindex:"-1"},[l("OneNote 笔记本、分区与会议记录 "),t("a",{class:"header-anchor",href:"#onenote-笔记本、分区与会议记录","aria-label":'Permalink to "OneNote 笔记本、分区与会议记录"'},"​")],-1)),e[1]||(e[1]=t("p",null,"OneNote 适合收集和组织过程信息，不要求像 Word 那样一开始就固定页面排版。本篇以一个项目笔记本组织会议、资料和行动项。Windows、Mac、网页版的功能和菜单可能不同，按实际版本操作。",-1)),s(a,{guide:o}),e[2]||(e[2]=h('<h2 id="structure" tabindex="-1">建立结构 <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;建立结构 {#structure}&quot;">​</a></h2><p>新建笔记本 <code>月报项目</code>，建立“会议记录、参考资料、操作说明”三个分区。在会议记录分区创建页面，标题采用 <code>2026-11-01 月报复盘</code>，让日期和主题都可检索。项目很多时可使用分区组，但不必为了分类精细建立太多层级。</p><p>笔记本是大范围的容器，分区按工作类型或主题组织，页面保存具体事件或内容。不要只用一张无限增长的“杂记”页面；也不要每记录一句话就开一个新笔记本，难以维护共享和搜索范围。</p><h2 id="meeting" tabindex="-1">做一页会议记录 <a class="header-anchor" href="#meeting" aria-label="Permalink to &quot;做一页会议记录 {#meeting}&quot;">​</a></h2><p>页面开头写会议时间、参与者、目的和相关材料链接。正文按以下块组织：讨论要点、已确认决策、未决问题、行动项。把事实记录和个人判断分开，重要决策注明确认者和日期。</p><table tabindex="0"><thead><tr><th>行动项</th><th>负责人</th><th>截止日期</th><th>状态</th></tr></thead><tbody><tr><td>核对 10 月订单口径</td><td>陈晨</td><td>2026-11-03</td><td>待处理</td></tr><tr><td>更新月报说明</td><td>李明</td><td>2026-11-04</td><td>待处理</td></tr></tbody></table><p>待办标签可以标记需要完成的条目，但勾选框本身不自动建立完整的团队任务分派或提醒体系。需要责任通知和自动提醒时，应配合团队实际使用的任务工具，并在笔记中保留链接。</p><h2 id="attachments" tabindex="-1">链接、附件与打印输出 <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;链接、附件与打印输出 {#attachments}&quot;">​</a></h2><p>插入文件链接适合指向持续维护的文档，权限和路径必须有效；插入附件通常保存一份副本，源文件后续变化不会自动同步到附件。插入打印输出便于逐页批注，但它也不是原文件的实时内容。</p><p>截图和录音等功能按版本检查。对截图补写来源和关键结论，避免以后只看到一张不知背景的图片。录音涉及参与者知情和组织规定，日常文字纪要足够时不必额外录制。</p><h2 id="sync" tabindex="-1">同步与共享 <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;同步与共享 {#sync}&quot;">​</a></h2><p>记录完成后检查同步状态，特别是离线编辑后恢复网络时。能在当前设备看到内容不代表服务器和另一设备已经收到；关闭设备前确认重要页面完成同步。</p><p>共享笔记本前了解权限范围，不要假设发送单页链接就只授予单页访问。若整个笔记本都包含内部资料，应按目标权限拆分到适当的共享空间，或仅导出经检查的页面。组织策略可能限制外部共享。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>建立上述结构和两条行动项，为月报源文件插入链接，在页面结尾写本次会议的两条决策。用搜索找到“口径”，从另一设备或网页版确认关键内容已同步。再检查附件是否只是旧副本，保证引用材料与会议结论对应。</p><p>参考：<a href="https://support.microsoft.com/en-us/onenote/onenote-help-and-learning/basic-tasks-in-onenote-on-windows" target="_blank" rel="noopener noreferrer">OneNote Windows 基础任务</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：把一次会议整理成可追踪的笔记 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：把一次会议整理成可追踪的笔记 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：建立项目容器 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：建立项目容器 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：文件 → 新建。</strong></p><p>在 Windows 桌面 OneNote 新建月报项目笔记本，确认保存位置和账号。通过分区标签旁的加号或右键菜单创建会议分区，再添加一页。笔记本、分区、页面是三个层次，先弄清当前所在位置，避免把同一项目记录散到多个个人笔记本。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：边记录边区分决定与行动 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：边记录边区分决定与行动 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 待办事项标记。</strong></p><p>页面标题写日期和主题，正文分目标、讨论、决策、行动四段。每条行动写负责人、截止日期、可验收结果，再用开始选项卡的待办标记加复选框。“讨论过某问题”不是行动项，不能仅靠一个勾选框替代任务描述。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：验证记录可被再次找到 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：验证记录可被再次找到 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 查看同步状态。</strong></p><p>完成后查看同步状态，确认没有错误再关闭页面；重新打开并搜索主题验证。需要分享给同事时，先确认共享范围通常涉及整个笔记本而非仅当前页，再按权限要求处理。敏感私人内容不应混在同一个待共享笔记本里。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>界面布局因 OneNote 客户端和选项变化，分区标签可能在顶部或左侧。附件、打印输出图像和文件链接的更新方式不同，引用工作文件时写清实际来源。</p><p>图示操作参考：<a href="https://support.microsoft.com/zh-cn/onenote/organize-your-notes" target="_blank" rel="noopener noreferrer">微软官方：OneNote 分区与笔记组织</a>。核对日期：2026-11-02；界面示意与练习案例为本站独立编写。</p>',30))])}}});export{f as __pageData,g as default};
